<?php
namespace Modules\BankingCoreDeposits\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\BankingCoreDeposits\Entities\DepositAccount; use Modules\BankingCoreDeposits\Entities\FixedDeposit; use Modules\BankingCoreDeposits\Services\FixedDepositService;
class FixedDepositController extends Controller { public function index(){ $fds=FixedDeposit::latest()->paginate(25); return view('bankingcoredeposits::fixed-deposits.index',compact('fds')); } public function create(){ $accounts=DepositAccount::where('account_type','fixed_deposit')->get(); return view('bankingcoredeposits::fixed-deposits.create',compact('accounts')); } public function store(Request $request, FixedDepositService $service){ $service->open($request->all()); return redirect()->route('banking.core-deposits.fixed-deposits.index')->with('status','FD opened'); } public function show(FixedDeposit $fixedDeposit){ return view('bankingcoredeposits::fixed-deposits.show',compact('fixedDeposit')); } public function edit(FixedDeposit $fixedDeposit){ return view('bankingcoredeposits::fixed-deposits.edit',compact('fixedDeposit')); } public function update(Request $request, FixedDeposit $fixedDeposit){ $fixedDeposit->update($request->all()); return back()->with('status','FD updated'); } public function destroy(FixedDeposit $fixedDeposit){ $fixedDeposit->delete(); return back(); } }
